/**
 * Boaz Notices
 * ------------
 * Boaz speaks to Ruth and tells her to stay with his servants, and praises her for all she has done for Naomi. Stage: a field at evening, a man in the shade of a wall, a woman at his feet; the kindness of a landowner, a blessing being spoken.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./ruth-kit.js.
 */

import { THREE, createScene, cityGate, house, wheat, pillar, person, birds } from './ruth-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 866511852, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [13, 0, -58], { name: 'city', r: [0, 0.09, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0xa48b5a, trim: 0x5f5135 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x947d52 });
    }
    W.backdrop(city);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0xeeca84, head: 0xffe696 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x9c8456 });
    W.disc([0, 6, -12], 5, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xd8b878, ry: 0.46, s: 1.06 });
    person(W, group, [4.5, 0, 6], { robe: 0x9c8456, ry: -0.01, s: 1.11 });

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
